import React from 'react';
import ReactDOM from 'react-dom/client';
import './index.css';
import App from './App';
import reportWebVitals from './reportWebVitals';

// Configure webpack-dev-server to use the correct WebSocket path
// This prevents conflicts with Socket.IO
if (module.hot) {
    const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    const host = window.location.host;
    module.hot.setOptionsAndConnect({
        path: '/ws',
        timeout: 2000,
        overlay: false,
        reload: true,
        log: true,
        websocket: true,
        name: 'webpack-dev-server',
    });
}

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
    <React.StrictMode>
        <App />
    </React.StrictMode>
);

reportWebVitals();
